// Convierte respuesta Metabase {cols, rows} → array de objetos
const body = $input.first().json;

// Detectar errores comunes de Metabase antes de parsear
if (body.errors)      throw new Error('Metabase auth error: ' + JSON.stringify(body.errors));
if (body.message)     throw new Error('Metabase error: ' + body.message);
if (body.error)       throw new Error('Metabase error: ' + body.error);
if (body.status && body.status !== 'completed') {
  throw new Error('Metabase status: ' + body.status + ' | ' + JSON.stringify(body).slice(0, 300));
}

const data = body.data || {};
const cols = (data.cols || []).map(c => c.name);
const rows = data.rows || [];

if (!cols.length) {
  throw new Error('Metabase sin columnas. Respuesta completa: ' + JSON.stringify(body).slice(0, 1000));
}

const metabase_rows = rows.map(row => {
  const obj = {};
  cols.forEach((col, i) => { obj[col] = row[i] ?? null; });
  return obj;
});

return [{ json: { metabase_rows, total: metabase_rows.length } }];

// Extrae los codigo_ot que ya existen en el Sheet (columna B)
const items = $input.all();
const sheet_codes = items
  .map(i => i.json.codigo_ot)
  .filter(v => v != null && v !== '');
return [{ json: { sheet_codes } }];

// Calcula qué OTs del Metabase faltan en el Sheet
// items_to_add: en Metabase pero NO en Sheet (nuevas + repuestas si alguien borró)
// items_to_log: en Metabase pero NO en el log Supabase (verdaderamente nuevas)
const metabaseRows = $('Parse Metabase Response').first().json.metabase_rows || [];
const sheetCodes   = new Set(($('Agregar Codigos Sheet').first().json.sheet_codes || []).map(String));
const logItems     = $input.all();
const logCodes     = new Set(logItems.map(i => i.json.codigo_ot).filter(Boolean).map(String));

const items_to_add = metabaseRows.filter(r => !sheetCodes.has(String(r.codigo_ot)));
const items_to_log = items_to_add.filter(r => !logCodes.has(String(r.codigo_ot)));

return [{ json: {
  has_items:    items_to_add.length > 0,
  items_to_add,
  items_to_log,
  count:        items_to_add.length,
  new_count:    items_to_log.length
} }];

// Construye INSERT para retencion_sheet_log
// ON CONFLICT DO NOTHING: maneja tanto nuevas como repuestas sin error
const items = $input.all();
if (!items.length) return [{ json: { sql: 'SELECT 1 -- nada que registrar', skipped: true } }];

const esc = s => String(s ?? '').replace(/'/g, "''");
const vals = items.map(i => {
  const r = i.json;
  return `('${esc(r['codigo_ot'])}', '${esc(r['Periodo'])}', '${esc(r['tipo_de_servicio'])}')`;
}).join(',\n');

const sql = 'INSERT INTO "Oraculo_Opex".retencion_sheet_log (codigo_ot, periodo, tipo_de_servicio)\nVALUES\n' + vals + '\nON CONFLICT (codigo_ot) DO NOTHING';

return [{ json: { sql, count: items.length } }];

// Parsea respuesta Anthropic del lote, recupera OTs originales y emite items clasificados
const httpResp  = $input.first().json;
const batchOts  = $('Build Batch Request').first().json.batch_ots || [];

const DEFAULT = { cotizacion:'En revisión', imputable_a:'En revisión', motivo_cierre:'En revisión' };

// Si Anthropic devolvió error HTTP
if (httpResp.error) {
  return batchOts.map(ot => ({ json: {
    ...ot,
    '¿Hay cotización asumida por el cliente?': 'En revisión',
    'Imputable a':    'En revisión',
    'Motivo de cierre': 'En revisión',
    'Comentarios':    'Error API lote: ' + JSON.stringify(httpResp.error).slice(0, 60)
  } }));
}

const text  = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
const clean = text.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

let classifications = [];
try {
  const parsed = JSON.parse(clean);
  classifications = Array.isArray(parsed) ? parsed : [];
} catch(e) {
  // Parse falló → todo el lote en revisión, pero el loop continúa
  return batchOts.map(ot => ({ json: {
    ...ot,
    '¿Hay cotización asumida por el cliente?': 'En revisión',
    'Imputable a':    'En revisión',
    'Motivo de cierre': 'En revisión',
    'Comentarios':    'Parse error en lote. CX revisar.'
  } }));
}

const classByCode = {};
for (const c of classifications) {
  if (c && c.codigo_ot) classByCode[String(c.codigo_ot)] = c;
}

return batchOts.map(ot => {
  const c = classByCode[String(ot.codigo_ot)] || { ...DEFAULT, comentarios: 'OT sin clasificar en lote.' };
  return { json: {
    ...ot,
    '¿Hay cotización asumida por el cliente?': c.cotizacion    || 'En revisión',
    'Imputable a':    c.imputable_a   || 'En revisión',
    'Motivo de cierre': c.motivo_cierre || 'En revisión',
    'Comentarios':    c.comentarios   || ''
  } };
});

// Per-item: construye el mensaje Slack con Block Kit + botones para esta OT
const ot = $input.item.json;

// ── Menciones fijas: CX siempre revisa ──
// Para obtener Slack User IDs: en Slack, click perfil → ⋮ → Copy member ID
const MARIA    = 'SLACK_ID_MARIA_FERNANDA';   // ← pega el ID real aquí
const NATALIA  = 'SLACK_ID_NATALIA_BURITICA'; // ← pega el ID real aquí
const mention  = '<@' + MARIA + '> <@' + NATALIA + '>';

const fmtCOP = (n) => {
  if (n == null || isNaN(n)) return '—';
  return '$' + Number(n).toLocaleString('es-CO', {maximumFractionDigits:0});
};

const obs   = (ot['Observacion de cierre'] || 'Sin observación').substring(0, 2800);
const razon = ot['Razon de cierre'] || '—';
const code  = ot.codigo_ot || 'OT';

const blocks = [
  {
    "type": "header",
    "text": { "type": "plain_text", "text": "📋 " + code + " — Pendiente", "emoji": true }
  },
  {
    "type": "section",
    "fields": [
      { "type": "mrkdwn", "text": "*Servicio:* " + (ot.tipo_de_servicio || '—') },
      { "type": "mrkdwn", "text": "*Fase:* " + (ot.fase_actual || '—') },
      { "type": "mrkdwn", "text": "*Frontera:* " + (ot.codigo_bia || '—') },
      { "type": "mrkdwn", "text": "*Contratista:* " + (ot.contratista || '—') },
      { "type": "mrkdwn", "text": "*Ciudad:* " + (ot.ciudad || '—') },
      { "type": "mrkdwn", "text": "*Costo:* " + fmtCOP(ot['costo_total ($)']) }
    ]
  },
  {
    "type": "section",
    "fields": [
      { "type": "mrkdwn", "text": "*Generada por:* " + (ot['Generada por'] || '—') },
      { "type": "mrkdwn", "text": "*Fecha:* " + (ot.fecha_programada || '—') },
      { "type": "mrkdwn", "text": "*Periodo:* " + (ot.Periodo || '—') },
      { "type": "mrkdwn", "text": "*Contract:* " + (ot.contract_id || '—') }
    ]
  },
  {
    "type": "section",
    "text": { "type": "mrkdwn", "text": "*Razón de cierre:* " + razon }
  },
  {
    "type": "section",
    "text": { "type": "mrkdwn", "text": "*Observación de cierre:*\n> " + obs.replace(/\n/g, '\n> ') }
  },
  { "type": "divider" },
  {
    "type": "section",
    "text": { "type": "mrkdwn", "text":
      "*🤖 Propuesta del clasificador:*\n" +
      "• *Imputable a:* `" + (ot['Imputable a'] || 'En revisión') + "`\n" +
      "• *Motivo de cierre:* `" + (ot['Motivo de cierre'] || 'En revisión') + "`\n" +
      "• *¿Cotización?:* `" + (ot['¿Hay cotización asumida por el cliente?'] || 'En revisión') + "`\n\n" +
      "*Análisis:* " + (ot.Comentarios || '—')
    }
  }
];

// Link del acta si existe
const linkAct = ot['Link de Act'];
if (linkAct && linkAct.startsWith('http')) {
  blocks.push({
    "type": "section",
    "text": { "type": "mrkdwn", "text": "📎 *Acta:* <" + linkAct + "|Ver acta>" }
  });
}

blocks.push({ "type": "divider" });

// Botones de acción
blocks.push({
  "type": "actions",
  "block_id": "ot_actions",
  "elements": [
    {
      "type": "button",
      "text": { "type": "plain_text", "text": "✅ Confirmar propuesta", "emoji": true },
      "style": "primary",
      "action_id": "confirm_ot",
      "value": code
    },
    {
      "type": "button",
      "text": { "type": "plain_text", "text": "✏️ Diligenciar formulario", "emoji": true },
      "action_id": "open_form",
      "value": code
    }
  ]
});

blocks.push({
  "type": "context",
  "elements": [{
    "type": "mrkdwn",
    "text": mention + " ← revisar esta OT"
  }]
});

return { json: {
  ...ot,
  slack_blocks: JSON.stringify(blocks),
  slack_text: 'OT ' + code + ' (' + (ot.tipo_de_servicio || '') + ' · ' + (ot.fase_actual || '') + ') — Revisión pendiente'
} };
